12	const STATUS_BY_CODE: Record<ApiErrorCode, number> = {
13	  UNAUTHORIZED: 401,
14	  BAD_REQUEST: 400,
15	  NOT_FOUND: 404,
16	  CONFLICT: 409,
17	  RATE_LIMITED: 429,
