1	/**
2	 * In-memory per-user token bucket. Good enough for a single long-lived Node
3	 * process on one VPS (see SPEC.md §3.1) — would need a shared store (Redis)
4	 * behind a load balancer.
5	 */
6	
7	export const RATE_LIMITS = {
8	  'recipes/search': 6,
9	  'recipes/adapt': 6,
10	  'vision': 10,
11	  tts: 60,
12	  'products/lookup': 30,
13	} as const;
14	
15	export type RateLimitRoute = keyof typeof RATE_LIMITS;
16	
17	interface Bucket {
18	  tokens: number;
19	  lastRefillMs: number;
20	}
21	
22	const buckets = new Map<string, Bucket>();
23	
24	export interface RateLimitResult {
25	  ok: boolean;
26	  retryAfterMs: number;
27	}
28	
29	export function checkRateLimit(userId: string, route: RateLimitRoute, now = Date.now()): RateLimitResult {
30	  const limitPerMinute = RATE_LIMITS[route];
31	  const key = `${userId}:${route}`;
32	  const refillPerMs = limitPerMinute / 60_000;
33	
34	  const existing = buckets.get(key);
35	  const bucket: Bucket = existing ?? { tokens: limitPerMinute, lastRefillMs: now };
36	  const elapsedMs = Math.max(0, now - bucket.lastRefillMs);
37	  bucket.tokens = Math.min(limitPerMinute, bucket.tokens + elapsedMs * refillPerMs);
38	  bucket.lastRefillMs = now;
39	
40	  if (bucket.tokens >= 1) {
41	    bucket.tokens -= 1;
42	    buckets.set(key, bucket);
43	    return { ok: true, retryAfterMs: 0 };
44	  }
45	
46	  buckets.set(key, bucket);
47	  const retryAfterMs = Math.ceil((1 - bucket.tokens) / refillPerMs);
48	  return { ok: false, retryAfterMs };
49	}
